import{_ as t,o as e,c as i,a3 as s}from"./chunks/framework.CVt6dz2a.js";const g=JSON.parse('{"title":"EP.03 相机与视锥体","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.03-camera-frustum.md","filePath":"comics/EP.03-camera-frustum.md","lastUpdated":1792595797000}'),r={name:"comics/EP.03-camera-frustum.md"};function o(l,a,n,h,d,p){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="ep-03-相机与视锥体" tabindex="-1">EP.03 相机与视锥体 <a class="header-anchor" href="#ep-03-相机与视锥体" aria-label="Permalink to &quot;EP.03 相机与视锥体&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/03-camera/basics">3.1 基础入门：透视相机与视锥体</a> 延伸阅读：<a href="./../guide/03-camera/advanced">进阶篇</a> · <a href="./../guide/03-camera/practice">实战篇</a> 动手演示：<a href="./../public/demos/camera/perspective-fov.html">perspective-fov 视场角实验</a> · <a href="./../public/demos/camera/orthographic-switch.html">orthographic-switch 透视正交切换</a> · <a href="./../public/demos/camera/four-viewports.html">four-viewports 四视口编辑器</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君想做一条无限贴地公路，地面和路面贴在一起后满屏斑马纹闪烁，转个角度就互相穿模。</td></tr><tr><td>② 揭秘</td><td>码叔画出视锥体：相机看得见的空间是个被 near/far 削平的四棱锥；斑马纹是 near 太小导致的深度缓冲精度问题（z-fighting）。</td></tr><tr><td>③ 实证</td><td>像素酱对比透视与正交相机：一个近大远小有空间感，一个尺寸不变适合工程图；再用 <code>setViewport</code> 拼出四视图编辑器。</td></tr><tr><td>④ 结案</td><td>码叔总结：near 尽量大、far 按需设；改任何投影参数都要 <code>updateProjectionMatrix()</code>。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-perspectivecamera-的四个参数" tabindex="-1">① PerspectiveCamera 的四个参数 <a class="header-anchor" href="#_1-perspectivecamera-的四个参数" aria-label="Permalink to &quot;① PerspectiveCamera 的四个参数&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PerspectiveCamera</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fov, aspect, near, far)</span></span></code></pre></div><ul><li><strong>fov</strong>：垂直视场角（度）。变小是望远镜（透视压缩），变大是广角（边缘变形），人眼约 60°；</li><li><strong>aspect</strong>：宽高比，应等于画布宽/高，不匹配画面会拉伸；</li><li><strong>near / far</strong>：近、远裁面距离，只有夹在视锥体内的物体才渲染（视锥剔除）。</li></ul><p>fov 改变的是&quot;视锥体张角&quot;，和移动相机都能改变取景，但机制完全不同：一个换镜头，一个换站位。</p><h3 id="_2-z-fighting-深度缓冲的精度战争" tabindex="-1">② z-fighting：深度缓冲的精度战争 <a class="header-anchor" href="#_2-z-fighting-深度缓冲的精度战争" aria-label="Permalink to &quot;② z-fighting：深度缓冲的精度战争&quot;">​</a></h3><p>GPU 用深度缓冲（depth buffer）记录每个像素最近的表面。near 太小、far 太大时，巨大的深度范围被压缩进有限的精度里，两个共面或极近的表面就无法区分前后，表现为闪烁的斑马纹。</p><p>经验法则：</p><ul><li><strong>near 尽量大</strong>：室内/产品场景 <code>0.1</code> 起步，别用 0.0001；</li><li><strong>far 按需要设</strong>：看得见 100 米就别设 10000；</li><li>必须共面的两个面（如贴花），用 <code>polygonOffset</code> 或手动拉开极小距离。</li></ul><h3 id="_3-透视-vs-正交" tabindex="-1">③ 透视 vs 正交 <a class="header-anchor" href="#_3-透视-vs-正交" aria-label="Permalink to &quot;③ 透视 vs 正交&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>PerspectiveCamera</th><th>OrthographicCamera</th></tr></thead><tbody><tr><td>平行线</td><td>远处汇聚（近大远小）</td><td>永远平行（尺寸不变）</td></tr><tr><td>适用</td><td>游戏、产品展示、写实场景</td><td>CAD、2.5D、编辑器顶/前/侧视图</td></tr><tr><td>参数</td><td>fov</td><td>left/right/top/bottom</td></tr></tbody></table><h3 id="_4-一帧多相机-四视口" tabindex="-1">④ 一帧多相机：四视口 <a class="header-anchor" href="#_4-一帧多相机-四视口" aria-label="Permalink to &quot;④ 一帧多相机：四视口&quot;">​</a></h3><p>同一渲染循环里反复&quot;设置视口 → 渲染&quot;即可在一个 canvas 上分屏：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setScissorTest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setViewport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, y, w, h)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setScissor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, y, w, h)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(scene, camera)</span></span></code></pre></div><p>四视口演示用一台透视 + 三台正交（顶/前/侧）模拟 3D 建模软件布局。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：改了 camera.fov 画面没反应？</strong> fov/aspect/near/far/zoom 任何一个改动后都必须 <code>camera.updateProjectionMatrix()</code>。</li><li><strong>Q：OrbitControls 下 camera.lookAt 不生效？</strong> 控制器每帧用 <code>controls.target</code> 覆盖相机朝向，应该改 target 而不是手动 lookAt。</li><li><strong>Q：正交相机下滚轮缩放没反应？</strong> 正交相机的&quot;缩放&quot;靠缩放 view 尺寸或调 <code>camera.zoom</code>，OrbitControls 已内置支持。</li><li><strong>Q：resize 后画面变形？</strong> aspect 与容器宽高比失配，重算 aspect 并更新投影矩阵。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>地面上的斑马线闪烁属于什么现象？最有效的两个缓解手段是什么？</li><li>想做一个建筑平面图（不允许近大远小），应该选哪种相机？</li><li>fov 从 50 调到 20 但相机不动，画面里的物体会怎样？为什么？</li></ol><details><summary>答案</summary><ol><li><strong>z-fighting（深度缓冲精度不足）</strong>；手段：<strong>near 尽量取大</strong>、<strong>far 按实际需要收紧</strong>；贴花类可加 polygonOffset。</li><li><strong>OrthographicCamera 正交相机</strong>，平行线保持平行、尺寸不随距离变化。</li><li>物体看起来被<strong>放大、视野变窄</strong>（望远镜效果）。fov 变小使视锥体张角收窄，同样屏幕容纳的场景变少，物体占比变大，但透视关系没有改变。</li></ol></details>`,24)])])}const k=t(r,[["render",o]]);export{g as __pageData,k as default};
